        ActivityTypeTerm: {
            /** @example scuba */
            key: string;
            /** @example Scuba diving */
            label: string;
            /** @enum {string} */
            category: "adventure" | "nature_wildlife" | "food_drink" | "arts_creativity" | "learning" | "culture_heritage" | "wellness" | "entertainment" | "community" | "sports" | "local_life" | "events";
        };
